void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 source = vrchSampleSource0(uv);
  float confidence = vrchReadSignal(0);
  vec2 center = vec2(vrchReadSignal(1), vrchReadSignal(2));
  vec2 size = vec2(max(0.05, uParam_body_width), max(0.08, uParam_body_height));
  vec2 shape = (uv - center) / size;
  float body = 1.0 - smoothstep(0.72, 1.0, length(shape));
  float luma = dot(source.rgb, vec3(0.2126, 0.7152, 0.0722));
  vec3 treated = mix(source.rgb, vec3(luma) * uParam_background_tint.rgb, uParam_desaturate);
  treated *= 1.0 - uParam_dim;
  float effectAmount = clamp(uParam_amount * confidence, 0.0, 1.0);
  vec3 color = mix(source.rgb, treated, effectAmount * (1.0 - body));
  vec4 tracking = vrchSampleSignalTexture(0, uv);
  color += uParam_skeleton_color.rgb * tracking.a * uParam_skeleton * confidence * 0.38;
  fragColor = vec4(color, source.a);
}
